const formatRuntime = (seconds:number) => {const minutes=Math.floor(seconds/60);const remainder=seconds%60;return minutes?`${minutes}m${remainder?` ${remainder}s`:''}`:`${seconds}s`;};
const blankProject = (contentLanguage: LanguageCode = 'en'): ProjectInput => ({ title: 'Untitled video', topic: '', script: '', hook: '', takeaway: '', engine: 'model', styleId: 'A2', aspectRatio: '16:9', durationSeconds: 60, voiceover: true, subtitles: true, soundEffects: false, contentLanguage, cartoonCast: [], scenes: [] });
