function App() {
  return <LanguageProvider><QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppRoutes /></WouterRouter></QueryClientProvider></LanguageProvider>;
}

function AppRoutes() {
  const { locale, setLocale, t } = useI18n();
  const [location, setLocation] = useLocation();
  const cache = useQueryClient();
  const session = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } });
  const user = session.data as SessionUser | undefined;
  const [mobileNav, setMobileNav] = useState(false);
  const [toast, setToast] = useState('');
  const [current, setCurrent] = useState<Project | null>(null);
  const projectsQuery = useListProjects({ query: { queryKey: getListProjectsQueryKey(), enabled: !!user } });
  const projects = (projectsQuery.data ?? []) as Project[];
  const rootCreate = useCreateProject();
  const logout = useLogOut();
  const savePreferences = useUpdateUserPreferences();
  const notify = (message: string) => setToast(t(message));
  useEffect(() => {
    if (user && user.locale !== locale) setLocale(user.locale);
  }, [user?.id, user?.locale]);
  const changeInterfaceLanguage = (next: LanguageCode) => {
    const previous = locale;
    setLocale(next);
    if (!user) return;
    savePreferences.mutate(
      { data: { locale: next, contentLanguage: user.contentLanguage } },
      {
        onSuccess: updated => cache.setQueryData(getGetCurrentUserQueryKey(), updated),
        onError: error => {
          setLocale(previous);
          notify(errorText(error));
        },
      },
    );
  };
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 2800); return () => window.clearTimeout(timer); }, [toast]);
  useEffect(() => {
    if (!projects.length) { setCurrent(null); return; }
    setCurrent(existing => {
      const latest = existing && projects.find(p => p.id === existing.id);
      if (!latest) return projects[0];
      return latest.approvedAt !== existing.approvedAt ? { ...existing, approvedAt: latest.approvedAt } : existing;
    });
  }, [projects]);
  const signOut = () => logout.mutate(undefined, { onSuccess: () => { cache.clear(); setCurrent(null); setLocation('/'); notify('Signed out securely'); }, onError: () => notify('Could not sign out. Try again.') });
  const isAdmin = user?.role === 'admin';
  return <div className="app-shell grain" dir={locale === 'ar' ? 'rtl' : 'ltr'} lang={locale === 'am' ? 'am-ET' : locale}>
    {user && <aside className={`sidebar ${mobileNav ? 'nav-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><Clapperboard size={19}/></div><div><div className="brand-name">STICKMAN<span> / DIRECTOR</span></div><div className="brand-kicker">{t('A STORYBOARD WORKSPACE')}</div></div><button className="mobile-close" data-testid="button-close-nav" onClick={()=>setMobileNav(false)} aria-label={t('Close navigation')}><X size={18}/></button></div>
      <div className="workspace-label mono">{t('YOUR STUDIO')} <span>01</span></div>
      <nav className="nav-links">
        <NavButton active={location==='/studio'} click={()=>{setLocation('/studio');setMobileNav(false)}} icon={<Layers3 size={17}/>} label="Studio"/>
        <NavButton active={location==='/projects'} click={()=>{setLocation('/projects');setMobileNav(false)}} icon={<FolderOpen size={17}/>} label="Projects" count={projects.length}/>
        <NavButton active={location==='/downloads'} click={()=>{setLocation('/downloads');setMobileNav(false)}} icon={<Download size={17}/>} label="Downloaded videos"/>
        <NavButton active={location==='/styles'} click={()=>{setLocation('/styles');setMobileNav(false)}} icon={<Film size={17}/>} label="Style library"/>
        <NavButton active={location==='/settings'} click={()=>{setLocation('/settings');setMobileNav(false)}} icon={<Settings2 size={17}/>} label="Settings"/>
        {isAdmin && <NavButton active={location==='/admin'} click={()=>{setLocation('/admin');setMobileNav(false)}} icon={<Shield size={17}/>} label="Admin desk"/>}
      </nav>
      <button className="new-project" data-testid="button-new-project-nav" onClick={()=>createNew()}><Plus size={16}/> {t('New project')}</button>
      <div className="side-divider"/>
      <div className="side-note"><div className="side-note-icon"><WandSparkles size={16}/></div><div><strong>{t('Make the brief first.')}</strong><p>{t('Shape a clear story, then direct each frame before the render.')}</p></div></div>
      <div className="sidebar-bottom"><div className="avatar">{initials(user.fullName)}</div><div><strong data-testid="text-current-user">{user.fullName}</strong><span>@{user.username} · {t(user.role)}</span></div><button className="side-logout" data-testid="button-sign-out" onClick={signOut} aria-label={t('Sign out securely')} title={t('Sign out securely')}><LogOut size={15}/></button></div>
    </aside>}
    {user && mobileNav && <button className="mobile-scrim" onClick={()=>setMobileNav(false)} aria-label={t('Close navigation')}/>}
    <main className={`main-area ${!user ? 'public-main' : ''}`}>
      {user && <header className="topbar"><button className="hamburger" data-testid="button-open-nav" onClick={()=>setMobileNav(true)} aria-label={t('Open menu')}><Menu size={20}/></button><div className="crumb"><span>Stickman Director</span><span className="crumb-slash">/</span><strong>{routeLabel(location)}</strong></div><div className="top-actions">{location==='/studio' && <span className="local-save" data-testid="status-private-workspace"><i className="saved-dot"/>{t('Private workspace')}</span>}<LanguageSwitcher onChange={changeInterfaceLanguage}/></div></header>}
      <div className={user?'content':'public-content'}>
        <Switch>
          <Route path="/sign-in"><AuthPage mode="login" locale={locale} onSuccess={u=>{setLocale(u.locale);cache.removeQueries({queryKey:getListProjectsQueryKey()});cache.removeQueries({queryKey:getListSocialProvidersQueryKey()});cache.removeQueries({queryKey:getListAdminUsersQueryKey()});cache.setQueryData(getGetCurrentUserQueryKey(),u);cache.invalidateQueries({queryKey:getListProjectsQueryKey()});setLocation(u.mustChangePassword?'/settings':'/studio');}}/></Route>
          <Route path="/sign-up"><AuthPage mode="signup" locale={locale} onSuccess={u=>{setLocale(u.locale);cache.removeQueries({queryKey:getListProjectsQueryKey()});cache.removeQueries({queryKey:getListSocialProvidersQueryKey()});cache.removeQueries({queryKey:getListAdminUsersQueryKey()});cache.setQueryData(getGetCurrentUserQueryKey(),u);cache.invalidateQueries({queryKey:getListProjectsQueryKey()});setLocation(u.mustChangePassword?'/settings':'/studio');}}/></Route>
          <Route path="/"><Landing user={user} onStudio={()=>setLocation('/studio')} onLocation={setLocation}/></Route>
          <Route path="/studio">{user ? <Editor user={user} projects={projects} projectsLoading={projectsQuery.isLoading} projectsError={projectsQuery.isError} retryProjects={()=>projectsQuery.refetch()} current={current} setCurrent={setCurrent} notify={notify} onProjects={()=>setLocation('/projects')} onStyles={()=>setLocation('/styles')}/> : <Landing user={user} onStudio={()=>setLocation('/sign-in')} onLocation={setLocation}/>}</Route>
          <Route path="/projects">{user ? <ProjectsPage projects={projects} defaultLanguage={user.contentLanguage} loading={projectsQuery.isLoading} error={projectsQuery.isError} retry={()=>projectsQuery.refetch()} open={p=>{setCurrent(p);setLocation('/studio');}} notify={notify} onBack={()=>setLocation('/studio')}/> : <Landing user={user} onStudio={()=>setLocation('/sign-in')} onLocation={setLocation}/>}</Route>
          <Route path="/downloads">{user ? <DownloadsPage user={user} onBack={()=>setLocation('/studio')} notify={notify}/> : <Landing user={user} onStudio={()=>setLocation('/sign-in')} onLocation={setLocation}/>}</Route>
          <Route path="/styles">{user ? <StylesPage selected={current?.styleId??'A2'} engine={current?.engine??'model'} onChoose={style=>{if(current)setCurrent({...current,styleId:style.id,engine:style.engine,approvedAt:null});setLocation('/studio');notify(`${style.name} selected`);}} onBack={()=>setLocation('/studio')}/> : <Landing user={user} onStudio={()=>setLocation('/sign-in')} onLocation={setLocation}/>}</Route>
          <Route path="/settings">{user ? <SettingsPage user={user} notify={notify} onBack={()=>setLocation('/studio')}/> : <Landing user={user} onStudio={()=>setLocation('/sign-in')} onLocation={setLocation}/>}</Route>
          <Route path="/admin">{isAdmin ? <AdminPage userId={user!.id} notify={notify} onBack={()=>setLocation('/settings')}/> : <NotFound back={()=>setLocation(user?'/studio':'/')}/>}</Route>
          <Route><NotFound back={()=>setLocation(user?'/studio':'/')}/></Route>
        </Switch>
      </div>
    </main>
    {toast&&<div className="toast" role="status" data-testid="status-toast"><Check size={16}/>{toast}</div>}
  </div>;

  function createNew() {
    rootCreate.mutate({data:blankProject(user?.contentLanguage ?? locale)},{onSuccess:p=>{setCurrent(p);cache.invalidateQueries({queryKey:getListProjectsQueryKey()});setLocation('/studio');notify('New project created');},onError:e=>notify(errorText(e))});
    setMobileNav(false);
  }
}

function NavButton({active,click,icon,label,count}:{active:boolean;click:()=>void;icon:ReactNode;label:string;count?:number}) {
  return <button className={`nav-item ${active?'active':''}`} onClick={click} data-testid={`nav-${label.toLowerCase().replaceAll(' ','-')}`}>{icon}{translateActive(label)}{count!==undefined&&<span className="nav-count">{count}</span>}</button>;
}
function PageBack({onClick,label}:{onClick:()=>void;label:string}) {
  return <button className="page-back" type="button" onClick={onClick} data-testid={`button-${label.toLowerCase().replaceAll(' ','-')}`}><ArrowLeft size={14}/>{translateActive(label)}</button>;
}

function PasswordField({label,value,onChange,autoComplete,testId,minLength=1,maxLength=128,required=true,placeholder,helper}:{label:string;value:string;onChange:(value:string)=>void;autoComplete:string;testId:string;minLength?:number;maxLength?:number;required?:boolean;placeholder?:string;helper?:string}) {
  const [visible,setVisible]=useState(false);
  return <label className="password-field">{translateActive(label)}<span className="password-input-wrap"><input data-testid={testId} autoComplete={autoComplete} type={visible?'text':'password'} required={required} minLength={minLength} maxLength={maxLength} value={value} onChange={event=>onChange(event.target.value)} placeholder={placeholder?translateActive(placeholder):undefined}/><button className="password-toggle" type="button" aria-label={`${translateActive(visible?'Hide':'Show')} ${translateActive(label).toLowerCase()}`} aria-pressed={visible} data-testid={`button-toggle-${testId.replace(/^input-/,'')}`} onClick={()=>setVisible(current=>!current)}>{visible?<EyeOff size={16}/>:<Eye size={16}/>}</button></span>{helper&&<small>{translateActive(helper)}</small>}</label>;
}
function initials(name:string){return name.split(/\s+/).slice(0,2).map(s=>s[0]?.toUpperCase()??'').join('')||'SD';}
function routeLabel(path:string){return translateActive(({'/studio':'Studio','/projects':'Projects','/downloads':'Downloaded videos','/styles':'Style library','/settings':'Account settings','/admin':'Admin desk'} as Record<string,string>)[path]??'Welcome');}
function errorText(error:unknown){return translateActive(error instanceof Error?error.message:'Something went wrong. Please try again.');}

function Landing({user,onStudio,onLocation}:{user?:SessionUser;onStudio:()=>void;onLocation:(path:string)=>void}) {
  const t=translateActive;
  return <div className="landing-page">
    <header className="landing-nav"><button className="landing-brand" onClick={()=>onLocation('/')} data-testid="link-brand-home"><span className="brand-mark"><Clapperboard size={18}/></span>STICKMAN <i>/</i> DIRECTOR</button><div className="landing-nav-links"><a href="#method" data-testid="link-method">{t('The method')}</a><a href="#deliverables" data-testid="link-deliverables">{t('What you make')}</a><LanguageSwitcher/>{user?<button className="btn btn-primary" data-testid="button-enter-studio" onClick={onStudio}>{t('Enter the studio')} <ArrowRight size={15}/></button>:<><button className="landing-signin" data-testid="link-sign-in" onClick={()=>onLocation('/sign-in')}>{t('Sign in')}</button><button className="btn btn-primary" data-testid="link-sign-up" onClick={()=>onLocation('/sign-up')}>{t('Create account')} <ArrowRight size={15}/></button></>}</div></header>
    <section className="landing-hero"><div className="hero-copy"><span className="eyebrow"><span className="eyebrow-line"/>{t('A SMALL STUDIO FOR BIG IDEAS')}</span><h1 className="display">{t('From rough thought')}<br/><em>{t('to ready-to-render.')}</em></h1><p>{t('Turn a good idea into a directed stickman storyboard — editable, frame by frame, and ready to render as an MP4.')}</p><div className="hero-actions"><button className="btn btn-primary hero-cta" onClick={()=>user?onStudio():onLocation('/sign-up')} data-testid="button-start-making">{t(user?'Open your studio':'Start making')} <ArrowRight size={16}/></button>{!user&&<button className="hero-secondary" onClick={()=>onLocation('/sign-in')} data-testid="button-existing-account">{t('I already have an account')}</button>}</div><div className="hero-proof"><span><BadgeCheck size={15}/> {t('Your projects stay yours')}</span><span><Layers3 size={15}/> {t('Editable scene direction')}</span></div></div>
      <div className="hero-board" aria-label={t('Illustrated storyboard sample')}><div className="board-top"><span className="mono">{t("DIRECTOR'S BOARD / 01")}</span><span className="board-live"><i/> {t('IN DEVELOPMENT')}</span></div><div className="board-scene scene-one"><span className="frame-label mono">{t('FRAME 01 · THE HOOK')}</span><div className="sketch-sun"/><div className="sketch-character"><i/><i/><i/><i/></div><div className="sketch-object">?</div><div className="sketch-ground"/></div><div className="board-caption"><span>01</span><p>{t('“Why does your phone battery hate the cold?”')}</p><span className="mono">06 SEC</span></div><div className="board-timeline"><i/><i/><i/><i/><i/><span>01:00</span></div><div className="board-stamp">{t('A STORY')}<br/>{t('IN MOTION')}</div></div>
    </section>
    <section className="landing-stats"><div><span className="mono">01 / {t('FIND THE POINT')}</span><strong>{t('One idea, clearly told.')}</strong></div><div><span className="mono">02 / {t('DIRECT THE FRAMES')}</span><strong>{t('Every scene stays editable.')}</strong></div><div><span className="mono">03 / {t('MAKE THE FILE')}</span><strong>{t('Render an MP4 to download.')}</strong></div></section>
    <section className="landing-method" id="method"><div className="section-side"><span className="eyebrow"><span className="eyebrow-line"/>{t('THE WORKFLOW')}</span><h2 className="display">{t('A director’s desk,')}<br/>{t('not a prompt box.')}</h2><p>{t('Good explainers are built on decisions. Keep those decisions visible, deliberate, and yours.')}</p></div><div className="method-steps"><article><span className="mono">01</span><div><h3>{t('Find the story spine')}</h3><p>{t('Set the topic, shape the script, name the hook and takeaway.')}</p></div><ArrowRight size={17}/></article><article><span className="mono">02</span><div><h3>{t('Direct each beat')}</h3><p>{t('Choose a visual language, then refine narration, framing, movement, and sound.')}</p></div><ArrowRight size={17}/></article><article><span className="mono">03</span><div><h3>{t('Take it to picture')}</h3><p>{t('Generate a first pass, edit it into shape, then render a downloadable MP4.')}</p></div><ArrowRight size={17}/></article></div></section>
    <section className="landing-deliverables" id="deliverables"><div className="deliverable-art"><div className="mini-frame"><span className="mono">{t('SHOT / MEDIUM')}</span><div className="little-stick"><i/><i/><i/><i/></div><div className="mini-sun"/></div><div className="deliverable-tag mono">{t('VISUAL METAPHOR')}<br/><b>{t('THE IDEA, MADE VISIBLE')}</b></div></div><div><span className="eyebrow"><span className="eyebrow-line"/>{t('FROM IDEA TO EXPORT')}</span><h2 className="display">{t('A working storyboard')}<br/>{t('with a real finish line.')}</h2><p>{t('Nothing gets flattened into a one-shot output. Your script, scenes, style, sound and timing remain in a production-ready project you can keep refining.')}</p><button className="btn btn-primary" onClick={()=>user?onStudio():onLocation('/sign-up')} data-testid="button-build-storyboard">{t('Build a storyboard')} <ArrowRight size={15}/></button></div></section>
    <section className="landing-account"><div><Shield size={20}/><span className="mono">{t('ACCOUNT BOUNDARIES')}</span></div><h2>{t('Private by design.')}<br/><em>{t('Clear when it matters.')}</em></h2><p>{t('Sign in to work on your own projects. Account access is username-based; an administrator can issue a one-time reset password if you ever lose yours. You’ll choose a new password immediately after signing in.')}</p><button className="text-link" onClick={()=>onLocation(user?'/settings':'/sign-up')} data-testid="link-account-details">{t(user?'Manage account':'Create your account')} <ArrowRight size={14}/></button></section>
    <footer className="landing-footer"><span>STICKMAN / DIRECTOR</span><span className="mono">{t('IDEAS INTO FRAME-BY-FRAME DIRECTION')}</span><button onClick={()=>onLocation('/sign-in')} data-testid="link-footer-sign-in">{t('Sign in')} <ArrowRight size={13}/></button></footer>
  </div>;
}

function AuthPage({mode,locale,onSuccess}:{mode:'login'|'signup';locale:LanguageCode;onSuccess:(user:SessionUser)=>void}) {
  const t=translateActive;
  const [,setLocation]=useLocation();
  const signup=useSignUp(); const login=useLogIn(); const isSignup=mode==='signup';
  const [fullName,setFullName]=useState('');const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [bootstrapToken,setBootstrapToken]=useState('');const [contentLanguage,setContentLanguage]=useState<LanguageCode>(locale);const [error,setError]=useState('');
  const pending=signup.isPending||login.isPending;
  const submit=(e:FormEvent)=>{e.preventDefault();setError('');if(password.length<(isSignup?6:1)){setError(t(isSignup?'Choose a fresh password with at least 6 characters.':'Enter your password.'));return;}
    if(isSignup)signup.mutate({data:{fullName:fullName.trim(),username:username.trim(),password,locale,contentLanguage,...(bootstrapToken.trim()?{bootstrapToken:bootstrapToken.trim()}:{})}},{onSuccess:u=>{setPassword('');setBootstrapToken('');onSuccess(u);},onError:e=>setError(errorText(e))});
    else login.mutate({data:{username:username.trim(),password}},{onSuccess:u=>{setPassword('');onSuccess(u);},onError:e=>setError(errorText(e))});
  };
  return <div className="auth-page"><div className="auth-illustration"><button className="auth-mark" onClick={()=>setLocation('/')} data-testid="button-auth-back"><ArrowLeft size={16}/> {t('Back')}</button><div className="auth-art"><span className="mono">{t('TAKE ONE / YOUR STORY')}</span><div className="auth-sun"/><div className="auth-stick"><i/><i/><i/><i/></div><div className="auth-horizon"/></div><span className="mono auth-art-note">{t('A blank frame is an invitation.')}</span></div><div className="auth-form-side"><div className="auth-form-wrap"><button className="auth-form-back" type="button" onClick={()=>setLocation('/')} data-testid="button-auth-back-mobile"><ArrowLeft size={15}/>{t('Back to home')}</button><div className="auth-language"><LanguageSwitcher/></div><div className="eyebrow"><span className="eyebrow-line"/>{t("THE DIRECTOR'S DESK")}</div><h1 className="display">{t(isSignup?'Make room for your idea.':'Back to the board.')}</h1><p className="auth-intro">{t(isSignup?'Create a private workspace and start shaping your first storyboard.':'Sign in to continue directing your projects.')}</p><form className="form-stack" onSubmit={submit} autoComplete="on">
    {isSignup&&<label>{t('Full name')}<input data-testid="input-full-name" autoComplete="name" required maxLength={120} value={fullName} onChange={e=>setFullName(e.target.value)} placeholder={t('Your name')}/></label>}
    {isSignup&&<label className="signup-content-language">{t('Default video content language')}<select data-testid="select-signup-content-language" value={contentLanguage} onChange={e=>setContentLanguage(e.target.value as LanguageCode)}><option value="en">English</option><option value="am">አማርኛ</option><option value="ar">العربية</option></select></label>}
    <label>{t('Username')}<input data-testid="input-username" autoComplete="username" required minLength={3} maxLength={32} pattern="[a-zA-Z0-9_]+" value={username} onChange={e=>setUsername(e.target.value)} placeholder={t('letters, numbers, underscore')}/></label>
    <PasswordField label="Password" testId="input-password" autoComplete={isSignup?'new-password':'current-password'} minLength={isSignup?6:1} value={password} onChange={setPassword} placeholder={isSignup?'At least 6 characters':'Your password'} helper={isSignup?'Choose a new password; never reuse a temporary reset password.':undefined}/>
    {isSignup&&<details className="bootstrap-details"><summary>{t('Have an administrator setup token?')}</summary><label>{t('Optional bootstrap token')}<input data-testid="input-bootstrap-token" type="password" autoComplete="off" maxLength={256} value={bootstrapToken} onChange={e=>setBootstrapToken(e.target.value)} placeholder={t('Leave blank unless provided')}/></label><small>{t('Only use a token from your workspace administrator.')}</small></details>}
    {error&&<div className="form-error" role="alert" data-testid="status-auth-error">{error}</div>}
    <button className="btn btn-primary form-submit" data-testid="button-auth-submit" disabled={pending}>{pending?t('Working…'):t(isSignup?'Create account':'Sign in')} <ArrowRight size={16}/></button>
    </form><div className="auth-recovery"><KeyRound size={15}/><p>{t('Username-only accounts cannot recover by email. Ask an administrator for a one-time temporary password; you must change it after signing in.')}</p></div><div className="auth-switch">{t(isSignup?'Already have an account?':'New to the studio?')} <button type="button" onClick={()=>setLocation(isSignup?'/sign-in':'/sign-up')} data-testid={isSignup?'link-switch-sign-in':'link-switch-sign-up'}>{t(isSignup?'Sign in':'Create an account')}</button></div></div></div></div>;
}

type ActionDialogConfig = {
  title: string;
  message: string;
  confirmLabel: string;
  inputLabel?: string;
  initialValue?: string;
  tone?: 'danger';
  onConfirm: (value: string) => void;
};

function ActionDialog({config,onClose}:{config:ActionDialogConfig|null;onClose:()=>void}) {
  const [value,setValue]=useState('');
  const inputRef=useRef<HTMLInputElement>(null);
  useEffect(()=>{setValue(config?.initialValue??'');},[config]);
  useEffect(()=>{if(config?.inputLabel)inputRef.current?.focus();},[config?.inputLabel]);
  const submit=(event:FormEvent<HTMLFormElement>)=>{
    event.preventDefault();
    if(!config)return;
    const cleaned=value.trim();
    if(config.inputLabel&&!cleaned){inputRef.current?.focus();return;}
    config.onConfirm(cleaned);
    onClose();
  };
  return <Dialog open={!!config} onOpenChange={open=>{if(!open)onClose();}}>
    {config&&<DialogContent className="director-dialog" data-testid="dialog-action">
      <DialogHeader className="director-dialog-header"><DialogTitle className="director-dialog-title">{translateActive(config.title)}</DialogTitle><DialogDescription className="director-dialog-copy">{translateActive(config.message)}</DialogDescription></DialogHeader>
      <form className="director-dialog-form" onSubmit={submit}>
        {config.inputLabel&&<label className="director-dialog-field">{translateActive(config.inputLabel)}<input ref={inputRef} data-testid="input-dialog-value" autoComplete="off" maxLength={160} required value={value} onChange={event=>setValue(event.target.value)}/></label>}
        <div className="director-dialog-actions"><button className="btn btn-outline" type="button" onClick={onClose} data-testid="button-dialog-back"><ArrowLeft size={14}/>{translateActive('Back')}</button><button className={`btn ${config.tone==='danger'?'dialog-danger':'btn-primary'}`} type="submit" data-testid="button-dialog-confirm">{translateActive(config.confirmLabel)}</button></div>
      </form>
    </DialogContent>}
  </Dialog>;
}

function Editor({user,projects,projectsLoading,projectsError,retryProjects,current,setCurrent,notify,onProjects,onStyles}:{user:SessionUser;projects:Project[];projectsLoading:boolean;projectsError:boolean;retryProjects:()=>void;current:Project|null;setCurrent:(p:Project)=>void;notify:(s:string)=>void;onProjects:()=>void;onStyles:()=>void}) {
  const t=translateActive;
  const create=useCreateProject();const update=useUpdateProject();const generate=useGenerateStoryboard();const render=useRenderVideo();const approve=useApproveProject();
  const [activeTab,setActiveTab]=useState<'idea'|'script'>('idea');
  const [dialog,setDialog]=useState<ActionDialogConfig|null>(null);
  const project=current;
  const patch=(updates:Partial<ProjectInput>)=>{if(project)setCurrent({...project,...updates,approvedAt:null});};
  const save=()=>{if(!project)return;update.mutate({id:project.id,data:projectInput(project)},{onSuccess:p=>{setCurrent(p);queryClient.invalidateQueries({queryKey:getListProjectsQueryKey()});notify('Project saved');},onError:e=>notify(errorText(e))});};
  const newProject=()=>create.mutate({data:blankProject(user.contentLanguage)},{onSuccess:p=>{setCurrent(p);queryClient.invalidateQueries({queryKey:getListProjectsQueryKey()});notify('New project ready');},onError:e=>notify(errorText(e))});
   const gen=()=>{if(!project?.topic.trim()){notify('Add a topic before generating a storyboard');return;}generate.mutate({data:{topic:project.topic,sourceScript:project.script||undefined,styleId:project.styleId,aspectRatio:project.aspectRatio,durationSeconds:project.durationSeconds,contentLanguage:project.contentLanguage,cartoonCast:CARTOON_STYLE_IDS.has(project.styleId)?castForProject(project.cartoonCast):undefined}},{onSuccess:d=>{patch({title:d.title,script:d.script,hook:d.hook,takeaway:d.takeaway,scenes:d.scenes});notify('Storyboard generated — review every scene');},onError:e=>notify(errorText(e))});};
  const requestRender=(projectId:string,title:string)=>render.mutate({data:{projectId}},{onSuccess:blob=>{const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${slug(title)}.mp4`;a.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000);queryClient.invalidateQueries({queryKey:getListDownloadedVideosQueryKey()});notify('MP4 downloaded and saved to your library');},onError:e=>notify(errorText(e))});
  const approveForRender=()=>{if(!project)return;setDialog({title:'Approve this storyboard?',message:'Review the script and every scene before approving. Any later edit will clear approval.',confirmLabel:'Approve for rendering',onConfirm:()=>update.mutate({id:project.id,data:projectInput(project)},{onSuccess:savedProject=>{setCurrent(savedProject);queryClient.invalidateQueries({queryKey:getListProjectsQueryKey()});approve.mutate({id:project.id},{onSuccess:approvedProject=>{setCurrent(approvedProject);queryClient.invalidateQueries({queryKey:getListProjectsQueryKey()});notify('Project approved for rendering');},onError:e=>notify(errorText(e))});},onError:e=>notify(errorText(e))})});};
  const doRender=()=>{if(!project||!project.approvedAt){notify('Approve this project before rendering');return;}if(!project.scenes.length){notify('Add at least one scene before rendering');return;}if(project.voiceover){const shortScene=project.scenes.find(scene=>{const words=scene.narration.trim().split(/\s+/).filter(Boolean).length;return words<Math.ceil(scene.seconds*1.45);});if(shortScene){notify(t('Add more narration to “{{title}}” so it can cover its {{seconds}}-second scene.',{title:shortScene.title,seconds:shortScene.seconds}));return;}const longScene=project.scenes.find(scene=>scene.narration.trim().split(/\s+/).filter(Boolean).length>Math.ceil(scene.seconds*3.2));if(longScene){notify(t('Shorten “{{title}}” or give it more screen time.',{title:longScene.title}));return;}}const message=project.voiceover?'Narration will be generated scene-by-scene and paced across the planned runtime. Animated word-highlight captions are included when Subtitles is on. Voiceover uses Replit AI credits.':'Voiceover is off, so the MP4 will have no audio. Turn it on to include narration and synchronized captions.';setDialog({title:'Render and download this video?',message,confirmLabel:'Render MP4',onConfirm:()=>requestRender(project.id,project.title)});};
   const addScene=()=>{const index=project?.scenes.length??0;const cartoon=CARTOON_STYLE_IDS.has(project?.styleId??'');patch({scenes:[...(project?.scenes??[]),{id:crypto.randomUUID(),title:`${t('Scene')} ${index+1}`,narration:'',visualDirection:'',seconds:6,...(cartoon?{entrance:'already-on-stage' as const,groupAction:'story-directed' as const,exit:'hold' as const,transitionToNext:'match-left' as const}:{})}]});};
  const updateScene=(id:string,updates:Partial<Scene>)=>patch({scenes:project!.scenes.map(s=>s.id===id?{...s,...updates}:s)});
   const chosen=styles.find(s=>s.id===project?.styleId)||styles[1];
   const cartoonStyle=CARTOON_STYLE_IDS.has(project?.styleId??'');
   const castMembers=castForProject(project?.cartoonCast);
   const updateCastMember=(index:number,updates:Partial<CartoonCastMember>)=>patch({cartoonCast:castMembers.map((member,i)=>i===index?{...member,...updates}:member)});
   const addCastMember=()=>{if(castMembers.length>=5)return;const index=castMembers.length;const colors=['#e9784f','#4b84ae','#6d9b78','#d59c47','#8263ae'];const skins=['#ffd65f','#fff5e8','#efbd91','#d09a6a','#8c5b43'];const names=['Nia','Kito'];patch({cartoonCast:[...castMembers,{id:crypto.randomUUID(),name:names[index-3]??`Character ${index+1}`,role:'Friend',personality:'',shirtColor:colors[index]!,skinTone:skins[index]!,hairStyle:index%2?'curly':'short',accessory:'none'}]});};
   const removeCastMember=(index:number)=>{if(castMembers.length<=2)return;patch({cartoonCast:castMembers.filter((_member,i)=>i!==index)});};
  const goBackToProjects=()=>{if(project&&projectHasUnsavedChanges(project,projects.find(saved=>saved.id===project.id))){setDialog({title:'Leave without saving?',message:'Your latest storyboard edits are not saved and will be discarded if you leave this project.',confirmLabel:'Discard changes',tone:'danger',onConfirm:onProjects});return;}onProjects();};
  if(projectsLoading)return <div className="editor-page fade-in"><div className="page-heading"><div><PageBack onClick={goBackToProjects} label="Back to projects"/><div className="eyebrow"><span className="eyebrow-line"/>{t('YOUR PRIVATE STUDIO')}</div><h1 className="display">{t('Opening the board.')}</h1><p className="page-subtitle">{t('Loading your account projects.')}</p></div></div><div className="loading-skeleton" data-testid="status-studio-loading"><i/><i/></div></div>;
  if(projectsError)return <div className="editor-page fade-in"><PageBack onClick={goBackToProjects} label="Back to projects"/><div className="error-panel" role="alert" data-testid="status-studio-error"><h2>{t('Your studio could not open.')}</h2><p>{t('Your projects remain on your account. Try loading them again.')}</p><button className="btn btn-outline" data-testid="button-retry-studio" onClick={retryProjects}>{t('Try again')}</button><button className="text-link" data-testid="link-studio-projects" onClick={onProjects}>{t('Go to projects')} <ArrowRight size={13}/></button></div></div>;
  if(!project)return <div className="editor-page fade-in"><div className="page-heading"><div><PageBack onClick={goBackToProjects} label="Back to projects"/><div className="eyebrow"><span className="eyebrow-line"/>{t('YOUR PRIVATE STUDIO')}</div><h1 className="display">{t('Start with a blank frame.')}</h1><p className="page-subtitle">{t('Create a project to begin directing.')}</p></div><button className="btn btn-primary" data-testid="button-create-first-project" disabled={create.isPending} onClick={newProject}><Plus size={15}/>{t('New project')}</button></div>{projects.length===0&&<div className="empty-board"><div className="empty-sketch"><div className="sketch-sun"/><div className="sketch-horizon"/><div className="sketch-person"><i/><i/><i/><i/></div></div><span className="mono empty-label">{t('YOUR STUDIO IS READY')}</span><h3>{t('Bring the first idea in.')}</h3><p>{t('Projects are private to your account and editable whenever you return.')}</p><button className="btn btn-primary" data-testid="button-create-first-project-empty" onClick={newProject}><Plus size={15}/>{t('Create a project')}</button><button className="text-link" data-testid="link-browse-projects-empty" onClick={onProjects}>{t('View projects')} <ArrowRight size={13}/></button></div>}</div>;
  const total=project.scenes.reduce((n,s)=>n+s.seconds,0);
  return <div className="editor-page fade-in">
    <div className="page-heading"><div><PageBack onClick={goBackToProjects} label="Back to projects"/><div className="eyebrow"><span className="eyebrow-line"/>{t('PROJECT WORKSPACE')} <span className="eyebrow-id mono">{project.id.slice(0,7).toUpperCase()}</span></div><input className="project-title display" data-testid="input-project-title" value={project.title} onChange={e=>patch({title:e.target.value})} aria-label={t('Project title')}/><p className="page-subtitle">{t('Turn the rough thought into a shootable story.')}</p></div><div className="heading-actions"><div className="heading-stamp"><span className="stamp-dot"/><span className="mono">{t('PRIVATE PROJECT')} · {user.username}</span></div><button className="btn btn-outline" data-testid="button-new-project" disabled={create.isPending} onClick={newProject}><Plus size={14}/>{t('New')}</button></div></div>
    <div className="editor-grid"><section className="left-column">
      <div className="panel idea-panel"><div className="section-head"><div className="section-index mono">01</div><div><h2>{t('Start with the idea')}</h2><p>{t('Give the story a point of view.')}</p></div><div className="tabs"><button className={activeTab==='idea'?'tab active':'tab'} data-testid="tab-project-idea" onClick={()=>setActiveTab('idea')}>{t('Idea')}</button><button className={activeTab==='script'?'tab active':'tab'} data-testid="tab-project-script" onClick={()=>setActiveTab('script')}>{t('Script')}</button></div></div>
        {activeTab==='idea'?<div className="field-wrap"><label className="field-label" htmlFor="topic">{t('What are you explaining?')}</label><textarea id="topic" data-testid="input-project-topic" className="idea-input" maxLength={2000} placeholder={t('For example: why your phone battery drains faster in the cold…')} value={project.topic} onChange={e=>patch({topic:e.target.value})}/><div className="field-foot"><span>{t('One clear sentence is plenty to begin.')}</span><span className="mono">{project.topic.length} / 2000</span></div></div>:<div className="field-wrap"><label className="field-label" htmlFor="script">{t('Your narration or working script')}</label><textarea id="script" data-testid="input-project-script" className="idea-input script-input" maxLength={20000} placeholder={t('Paste a script, rough notes, or a voiceover draft…')} value={project.script} onChange={e=>patch({script:e.target.value})}/><div className="field-foot"><span>{t('Use this as source material for your storyboard.')}</span><span className="mono">{project.script.length} {t('chars')}</span></div></div>}
        <div className="project-language-row"><label className="field-label" htmlFor="project-content-language">{t('Video content language')}<select id="project-content-language" data-testid="select-project-content-language" value={project.contentLanguage} onChange={e=>patch({contentLanguage:e.target.value as LanguageCode})}><option value="en">English</option><option value="am">አማርኛ</option><option value="ar">العربية</option></select></label><small>{t('Choose the language used for new storyboards, narration, on-screen text, captions, and social copy.')}</small></div>
        <div className="field-row"><label className="field-label">{t('Story hook')}<input data-testid="input-project-hook" className="text-field" maxLength={1000} value={project.hook} onChange={e=>patch({hook:e.target.value})} placeholder={t('A first line that earns attention')}/></label><label className="field-label">{t('Takeaway')}<input data-testid="input-project-takeaway" className="text-field" maxLength={1000} value={project.takeaway} onChange={e=>patch({takeaway:e.target.value})} placeholder={t('What should viewers remember?')}/></label></div>
        <div className="engine-select"><span className="field-label">{t('Choose a workflow engine')}</span><div className="engine-options"><button className={`engine-choice ${project.engine==='model'?'selected':''}`} data-testid="button-engine-model" onClick={()=>patch({engine:'model',styleId:project.styleId.startsWith('A')?project.styleId:'A2'})}><span className="engine-symbol"><Sparkles size={17}/></span><span><b>{t('Model Engine')}</b><small>{t('Prompt-led visual direction')}</small></span>{project.engine==='model'&&<Check className="engine-check" size={16}/>}</button><button className={`engine-choice ${project.engine==='code'?'selected':''}`} data-testid="button-engine-code" onClick={()=>patch({engine:'code',styleId:project.styleId.startsWith('B')?project.styleId:'B1'})}><span className="engine-symbol code"><FileText size={17}/></span><span><b>{t('Code Engine')}</b><small>{t('Structured scene direction')}</small></span>{project.engine==='code'&&<Check className="engine-check" size={16}/>}</button></div></div>
        <div className="style-row"><div><span className="field-label">{t('Visual style')}</span><button className="style-select" data-testid="button-selected-style" onClick={onStyles}><span className="style-swatch" style={{backgroundImage:chosen.image?`url("${imageUrl(chosen.image)}")`:undefined}}/><span className="style-select-text"><b>{t(chosen.name)}</b><small>{t(project.engine==='model'?'Model Engine':'Code Engine')}</small></span><ChevronDown size={16}/></button></div><button className="text-link" data-testid="link-browse-styles" onClick={onStyles}>{t('Browse styles')} <ArrowRight size={13}/></button></div>
      </div>
      <div className="panel setup-panel"><div className="section-head compact"><div className="section-index mono">02</div><div><h2>{t('Set the frame')}</h2><p>{t('Production choices for this brief.')}</p></div></div>
        <div className="setup-grid"><div><span className="field-label">{t('Aspect ratio')}</span><div className="ratio-options"><button className={`ratio-choice ${project.aspectRatio==='16:9'?'on':''}`} data-testid="button-ratio-landscape" onClick={()=>patch({aspectRatio:'16:9'})}><span className="ratio-icon wide"/>{t('Landscape')} <small>16:9</small></button><button className={`ratio-choice ${project.aspectRatio==='9:16'?'on':''}`} data-testid="button-ratio-portrait" onClick={()=>patch({aspectRatio:'9:16'})}><span className="ratio-icon vertical"/>{t('Portrait')} <small>9:16</small></button></div></div><div className="duration-setting"><label className="field-label" htmlFor="duration">{t('Target duration')}</label><div className="duration-control"><input id="duration" data-testid="input-duration" type="number" min="15" max="600" value={project.durationSeconds} onChange={e=>patch({durationSeconds:Math.min(600,Math.max(15,Number(e.target.value)||15))})}/><span>{t('seconds')}</span></div><div className="duration-range"><input data-testid="input-duration-range" aria-label={t('Duration in seconds')} type="range" min="15" max="180" step="5" value={Math.min(project.durationSeconds,180)} onChange={e=>patch({durationSeconds:Number(e.target.value)})}/><div><span>15s</span><span>3m+</span></div><small className="runtime-note">{t('Selected')} {formatRuntime(project.durationSeconds)} · {t('voiceover paced across the scene sequence')}</small></div></div></div>
        <div className="audio-settings"><span className="field-label">{t('Audio & accessibility')}</span><Toggle label="Voiceover" icon={<Mic2 size={16}/>} checked={project.voiceover} onChange={v=>patch({voiceover:v})} testId="toggle-voiceover"/><Toggle label="Subtitles" icon={<FileText size={16}/>} checked={project.subtitles} onChange={v=>patch({subtitles:v})} testId="toggle-subtitles"/>{project.voiceover?<small className="audio-credit-note" data-testid="note-voiceover-credit">{t('Voiceover is split by scene and paced to the sequence’s planned runtime using Replit AI credits.')}</small>:<small className="audio-credit-note" data-testid="note-voiceover-off">{t('Voiceover is off; the MP4 will have no audio.')}</small>}<small className="audio-credit-note" data-testid="note-render-motion">{t('Scenes use topic-based backgrounds, directed stickman actions, and animated camera motion.')}</small><small className="audio-credit-note">{t('Subtitles animate with the narration when enabled. Scene sound cues are still not mixed as sound effects.')}</small></div>
       </div>
       {cartoonStyle&&<div className="panel cartoon-cast-panel" data-testid="panel-cartoon-cast"><div className="cast-panel-heading"><div><span className="field-label">{t('RECURRING CARTOON CAST')}</span><h2>{t('Shape your recurring cast')}</h2><p>{t('Names, roles, looks, and personalities stay consistent across scenes.')}</p></div><span className="cast-count mono">{castMembers.length} / 5</span></div><div className="cast-member-grid">{castMembers.map((member,index)=><article className="cast-member-card" key={member.id} data-testid={`card-cast-member-${member.id}`}><div className="cast-member-heading"><span><i style={{backgroundColor:member.shirtColor}}/>{t('Character {{number}}',{number:index+1})}</span>{castMembers.length>2&&<button className="cast-remove" type="button" data-testid={`button-remove-cast-${member.id}`} aria-label={t('Remove {{name}}',{name:member.name})} onClick={()=>removeCastMember(index)}><Trash2 size={13}/></button>}</div><div className="cast-field-grid"><label>{t('Name')}<input data-testid={`input-cast-name-${member.id}`} maxLength={40} value={member.name} onChange={e=>updateCastMember(index,{name:e.target.value})}/></label><label>{t('Role')}<input data-testid={`input-cast-role-${member.id}`} maxLength={60} value={member.role} onChange={e=>updateCastMember(index,{role:e.target.value})}/></label><label className="cast-personality">{t('Personality')}<input data-testid={`input-cast-personality-${member.id}`} maxLength={120} value={member.personality??''} placeholder={t('How they act in the story')} onChange={e=>updateCastMember(index,{personality:e.target.value})}/></label><label>{t('Shirt color')}<span className="color-input-wrap"><input data-testid={`input-cast-shirt-${member.id}`} type="color" value={member.shirtColor} aria-label={t('Shirt color for {{name}}',{name:member.name})} onChange={e=>updateCastMember(index,{shirtColor:e.target.value})}/><code>{member.shirtColor.toUpperCase()}</code></span></label><label>{t('Skin tone')}<span className="color-input-wrap"><input data-testid={`input-cast-skin-${member.id}`} type="color" value={member.skinTone} aria-label={t('Skin tone for {{name}}',{name:member.name})} onChange={e=>updateCastMember(index,{skinTone:e.target.value})}/><code>{member.skinTone.toUpperCase()}</code></span></label><label>{t('Hair')}<select data-testid={`select-cast-hair-${member.id}`} value={member.hairStyle} onChange={e=>updateCastMember(index,{hairStyle:e.target.value as CartoonCastMember['hairStyle']})}><option value="short">{t('Short')}</option><option value="curly">{t('Curly')}</option><option value="long">{t('Long')}</option></select></label><label>{t('Accessory')}<select data-testid={`select-cast-accessory-${member.id}`} value={member.accessory} onChange={e=>updateCastMember(index,{accessory:e.target.value as CartoonCastMember['accessory']})}><option value="none">{t('None')}</option><option value="cap">{t('Cap')}</option><option value="glasses">{t('Glasses')}</option><option value="headband">{t('Headband')}</option><option value="backpack">{t('Backpack')}</option><option value="bow">{t('Bow')}</option></select></label></div></article>)}</div><button className="cast-add-button" type="button" data-testid="button-add-cast-member" disabled={castMembers.length>=5} onClick={addCastMember}><Plus size={14}/>{t('Add character')} <span>{t('up to 5')}</span></button></div>}
     </section>
     <section className="right-column"><div className="storyboard-title"><div><div className="eyebrow"><span className="eyebrow-line"/>{t('STORYBOARD')} <span className="eyebrow-id mono">03</span></div><h2 className="display">{t('Shape the sequence')}</h2><p>{t('A practical plan for what viewers see and hear.')}</p></div><div className="generate-wrap"><button className="draft-button" data-testid="button-generate-storyboard" disabled={generate.isPending||!project.topic.trim()} onClick={gen} aria-busy={generate.isPending}><WandSparkles size={15}/>{generate.isPending?t('Building…'):t('Generate storyboard')}</button><small aria-live="polite">{generate.isPending?t('Creating a draft. Keep this page open.'):t('Uses Replit credits per generation.')}</small></div></div>
      <div className="draft-note"><Sparkles size={14}/><span>{t('AI creates an editable first draft. Review and refine every beat before rendering.')}</span></div>
        <div className="storyboard-meta"><span><b>{String(project.scenes.length).padStart(2,'0')}</b> {t('scenes')}</span><span className="meta-sep">/</span><span><b>{formatRuntime(total)}</b> {t('planned')}</span><span className="meta-spacer"/><span className="format-pill">{project.aspectRatio}</span></div>
       <div className="scene-list">{project.scenes.length===0?<div className="empty-board"><div className="empty-sketch"><div className="sketch-sun"/><div className="sketch-horizon"/><div className="sketch-person"><i/><i/><i/><i/></div><div className="sketch-frame">{t('FRAME 01')}</div></div><span className="mono empty-label">{t('YOUR FIRST FRAME IS A THOUGHT')}</span><h3>{t('Let’s put it on the board.')}</h3><p>{t('Add your own scenes or generate an editable storyboard from your topic.')}</p><button className="btn btn-primary" data-testid="button-empty-generate" disabled={generate.isPending||!project.topic.trim()} onClick={gen}><WandSparkles size={15}/>{t('Generate a starting storyboard')}</button><button className="empty-add" data-testid="button-empty-add-scene" onClick={addScene}><Plus size={15}/>{t('Start with a blank scene instead')}</button></div>:project.scenes.map((scene,i)=><article className="scene-card" key={scene.id} data-testid={`card-scene-${scene.id}`}><div className="scene-rail"><span className="scene-number mono">{String(i+1).padStart(2,'0')}</span><div className="scene-thumb" style={{backgroundImage:chosen.image?`linear-gradient(0deg,rgba(22,30,37,.35),transparent),url("${imageUrl(chosen.image)}")`:undefined}}><span className="thumb-ratio">{project.aspectRatio}</span></div></div><div className="scene-body"><div className="scene-top"><input data-testid={`input-scene-title-${scene.id}`} aria-label={`${t('Scene')} ${i+1} ${t('title')}`} className="scene-name" value={scene.title} onChange={e=>updateScene(scene.id,{title:e.target.value})}/><div className="scene-actions"><div className="reorder"><button data-testid={`button-scene-up-${scene.id}`} disabled={i===0} onClick={()=>{const a=[...project.scenes];[a[i-1],a[i]]=[a[i],a[i-1]];patch({scenes:a});}} aria-label={t('Move scene up')}><ArrowUp size={13}/></button><button data-testid={`button-scene-down-${scene.id}`} disabled={i===project.scenes.length-1} onClick={()=>{const a=[...project.scenes];[a[i+1],a[i]]=[a[i],a[i+1]];patch({scenes:a});}} aria-label={t('Move scene down')}><ArrowDown size={13}/></button></div><button className="icon-button delete-scene" data-testid={`button-delete-scene-${scene.id}`} onClick={()=>patch({scenes:project.scenes.filter(s=>s.id!==scene.id)})} aria-label={t('Delete scene')}><Trash2 size={15}/></button></div></div>
          <label className="mini-label" htmlFor={`narration-${scene.id}`}>{t('NARRATION')}</label><textarea id={`narration-${scene.id}`} data-testid={`input-scene-narration-${scene.id}`} className="scene-text narration" value={scene.narration} onChange={e=>updateScene(scene.id,{narration:e.target.value})}/><small className={`narration-coverage ${(scene.narration.trim().split(/\s+/).filter(Boolean).length<Math.ceil(scene.seconds*1.45))?'needs-words':''}`} data-testid={`note-narration-coverage-${scene.id}`}>{scene.narration.trim().split(/\s+/).filter(Boolean).length} {t('words')} · {t('aim for')} {Math.ceil(scene.seconds*1.45)} {t('or more for this')} {scene.seconds}-{t('second scene')}</small>
         <label className="mini-label" htmlFor={`visual-${scene.id}`}>{t('VISUAL DIRECTION')}</label><textarea id={`visual-${scene.id}`} data-testid={`input-scene-visual-${scene.id}`} className="scene-text" value={scene.visualDirection} onChange={e=>updateScene(scene.id,{visualDirection:e.target.value})}/>
          <div className="scene-extra-grid"><label>{t('Shot type')}<input data-testid={`input-scene-shot-${scene.id}`} value={scene.shotType??''} onChange={e=>updateScene(scene.id,{shotType:e.target.value})} placeholder={t('Wide, close-up…')}/></label><label>{t('Visual metaphor')}<input data-testid={`input-scene-metaphor-${scene.id}`} value={scene.visualMetaphor??''} onChange={e=>updateScene(scene.id,{visualMetaphor:e.target.value})} placeholder={t('The central image')}/></label><label>{t('On-screen text')}<input data-testid={`input-scene-text-${scene.id}`} value={scene.onScreenText??''} onChange={e=>updateScene(scene.id,{onScreenText:e.target.value})} placeholder={t('Caption or label')}/></label><label>{t('Camera move')}<input data-testid={`input-scene-camera-${scene.id}`} value={scene.cameraMove??''} onChange={e=>updateScene(scene.id,{cameraMove:e.target.value})} placeholder={t('Pan, hold…')}/></label><label>{t('Sound cue')}<input data-testid={`input-scene-sound-${scene.id}`} value={scene.soundCue??''} onChange={e=>updateScene(scene.id,{soundCue:e.target.value})} placeholder={t('Optional cue')}/></label></div>
          {cartoonStyle&&<div className="scene-choreography" data-testid={`scene-choreography-${scene.id}`}><div className="choreography-heading"><span className="field-label">{t('SCENE CHOREOGRAPHY')}</span><small>{t('Direct how the cast moves into, through, and out of this scene.')}</small></div><div className="choreography-fields"><label>{t('Entrance')}<select data-testid={`select-scene-entrance-${scene.id}`} value={scene.entrance??(i===0?'walk-in-left':'already-on-stage')} onChange={e=>updateScene(scene.id,{entrance:e.target.value as Scene['entrance']})}><option value="already-on-stage">{t('Already on stage')}</option><option value="walk-in-left">{t('Walk in from left')}</option><option value="walk-in-right">{t('Walk in from right')}</option><option value="run-in-left">{t('Run in from left')}</option><option value="run-in-right">{t('Run in from right')}</option><option value="pop-in">{t('Pop in together')}</option></select></label><label>{t('Group movement')}<select data-testid={`select-scene-group-action-${scene.id}`} value={scene.groupAction??'story-directed'} onChange={e=>updateScene(scene.id,{groupAction:e.target.value as Scene['groupAction']})}><option value="story-directed">{t('Follow the story')}</option><option value="talk-and-react">{t('Talk and react')}</option><option value="walk-together">{t('Walk together')}</option><option value="point-together">{t('Point together')}</option><option value="celebrate-together">{t('Celebrate together')}</option></select></label><label>{t('Exit')}<select data-testid={`select-scene-exit-${scene.id}`} value={scene.exit??'hold'} onChange={e=>updateScene(scene.id,{exit:e.target.value as Scene['exit']})}><option value="hold">{t('Stay for the next scene')}</option><option value="walk-off-left">{t('Walk off left')}</option><option value="walk-off-right">{t('Walk off right')}</option><option value="run-off-left">{t('Run off left')}</option><option value="run-off-right">{t('Run off right')}</option><option value="exit-together">{t('Exit together')}</option></select></label>{i<project.scenes.length-1&&<label>{t('Transition to next scene')}<select data-testid={`select-scene-transition-${scene.id}`} value={scene.transitionToNext??'match-left'} onChange={e=>updateScene(scene.id,{transitionToNext:e.target.value as Scene['transitionToNext']})}><option value="cut">{t('Clean cut')}</option><option value="dissolve">{t('Soft dissolve')}</option><option value="wipe-left">{t('Wipe left')}</option><option value="wipe-right">{t('Wipe right')}</option><option value="match-left">{t('Match movement left')}</option><option value="match-right">{t('Match movement right')}</option></select></label>}</div></div>}
         <div className="scene-foot"><span className="scene-cue"><span/>{t('DIRECTED SCENE')}</span><label className="seconds-label">{t('Duration')} <input data-testid={`input-scene-duration-${scene.id}`} type="number" min="1" max="90" value={scene.seconds} onChange={e=>updateScene(scene.id,{seconds:Math.max(1,Math.min(90,Number(e.target.value)||1))})}/> {t('sec')}</label></div></div></article>)}</div>
       {project.scenes.length>0&&<button className="add-scene" data-testid="button-add-scene" onClick={addScene}><Plus size={16}/>{t('Add a scene')}</button>}
        <div className={`approval-step ${project.approvedAt?'approved':''}`} data-testid="status-project-approval"><div className="approval-copy"><span className="mono">{project.approvedAt?t('APPROVED FOR PRODUCTION'):t('REVIEW GATE · REQUIRED')}</span><strong>{project.approvedAt?t('This version is approved.'):t('Review the board, then approve it.')}</strong><p>{project.approvedAt?`${t('Approved')} ${new Date(project.approvedAt).toLocaleString()}. ${t('Any edits or saves clear approval.')}`:t('Approval saves your current ProjectInput first, then unlocks MP4 rendering.')}</p></div><div className="brief-actions"><button className="btn btn-outline" data-testid="button-save-changes" disabled={update.isPending||approve.isPending} onClick={save} aria-busy={update.isPending}><Check size={15}/>{update.isPending?t('Saving…'):t('Save changes')}</button>{!project.approvedAt&&<button className="btn btn-approve" data-testid="button-approve-project" disabled={update.isPending||approve.isPending||render.isPending||project.scenes.length===0} onClick={approveForRender} aria-busy={approve.isPending}><BadgeCheck size={15}/>{update.isPending||approve.isPending?t('Saving & approving…'):t('Approve for rendering')}</button>}<button className="btn btn-primary" data-testid="button-render-video" disabled={!project.approvedAt||render.isPending||update.isPending||approve.isPending||project.scenes.length===0} onClick={doRender} aria-busy={render.isPending}><Download size={15}/>{render.isPending?t('Rendering…'):!project.approvedAt?t('Approve to unlock render'):t('Render & download MP4')}</button></div></div>
       {(update.isPending||approve.isPending)&&<div className="render-progress" role="status" aria-live="polite" data-testid="status-approval-progress"><i/>{t('Saving your approved storyboard…')}</div>}
       {render.isPending&&<div className="render-progress" role="status" aria-live="polite" data-testid="status-render-progress"><i/>{t('Rendering and saving your MP4. Keep this page open.')}</div>}
      {approve.isError&&<div className="inline-error" role="alert" data-testid="status-approval-error">{errorText(approve.error)}</div>}
      {render.isError&&<div className="inline-error" role="alert" data-testid="status-render-error">{errorText(render.error)}</div>}
     </section></div><footer className="editor-footer"><span>{t('Made for the part before the render.')}</span><span className="mono">{t('PRIVATE PROJECT')} · {t(chosen.name)}</span></footer><ActionDialog config={dialog} onClose={()=>setDialog(null)}/>
  </div>;
}
function Toggle({label,icon,checked,onChange,testId}:{label:string;icon:ReactNode;checked:boolean;onChange:(v:boolean)=>void;testId:string}) { return <button className={`toggle-row ${checked?'checked':''}`} data-testid={testId} aria-pressed={checked} onClick={()=>onChange(!checked)}><span className="toggle-icon">{icon}</span><span>{translateActive(label)}</span><span className="toggle-switch"><i/></span></button>; }
function slug(value:string){return value.trim().replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'stickman-storyboard';}
function projectInput(project:Project):ProjectInput { const {id,createdAt,updatedAt,approvedAt,...input}=project; void id; void createdAt; void updatedAt; void approvedAt; return input; }
function projectHasUnsavedChanges(current:Project,saved?:Project) {
  if(!saved)return true;
  const currentInput=projectInput(current);
  const savedInput=projectInput(saved);
  return Object.keys(currentInput).some(key=>{
    const field=key as keyof ProjectInput;
    return JSON.stringify(currentInput[field])!==JSON.stringify(savedInput[field]);
  });
}

function ProjectsPage({projects,defaultLanguage,loading,error,retry,open,notify,onBack}:{projects:Project[];defaultLanguage:LanguageCode;loading:boolean;error:boolean;retry:()=>void;open:(p:Project)=>void;notify:(s:string)=>void;onBack:()=>void}) {
  const t=translateActive;
  const create=useCreateProject();const update=useUpdateProject();const remove=useDeleteProject();const cache=useQueryClient();
  const [query,setQuery]=useState('');
  const [dialog,setDialog]=useState<ActionDialogConfig|null>(null);
  const list=useMemo(()=>projects.filter(p=>`${p.title} ${p.topic}`.toLowerCase().includes(query.toLowerCase())),[projects,query]);
  const createOne=()=>create.mutate({data:blankProject(defaultLanguage)},{onSuccess:p=>{cache.invalidateQueries({queryKey:getListProjectsQueryKey()});open(p);},onError:e=>notify(errorText(e))});
  const rename=(p:Project)=>setDialog({title:'Rename this project',message:'Choose a clear title for this video project.',confirmLabel:'Save title',inputLabel:'Project title',initialValue:p.title,onConfirm:value=>{const title=value.trim();if(!title||title===p.title)return;update.mutate({id:p.id,data:{...projectInput(p),title}},{onSuccess:()=>{cache.invalidateQueries({queryKey:getListProjectsQueryKey()});notify('Project renamed');},onError:e=>notify(errorText(e))});}});
  const del=(p:Project)=>setDialog({title:'Delete this project?',message:t('“{{title}}” and its storyboard will be permanently deleted. This cannot be undone.',{title:p.title}),confirmLabel:'Delete project',tone:'danger',onConfirm:()=>remove.mutate({id:p.id},{onSuccess:()=>{cache.invalidateQueries({queryKey:getListProjectsQueryKey()});notify('Project deleted');},onError:e=>notify(errorText(e))})});
  return <div className="library-page fade-in"><div className="library-heading"><div><PageBack onClick={onBack} label="Back to studio"/><div className="eyebrow"><span className="eyebrow-line"/>{t('YOUR PRIVATE WORKSPACE')}</div><h1 className="display">{t('Projects')}<span className="heading-period">.</span></h1><p>{t('Your story files, saved to your account and ready to direct again.')}</p></div><button className="btn btn-primary create-top" data-testid="button-create-project" disabled={create.isPending} onClick={createOne}><Plus size={16}/>{t('New project')}</button></div><div className="library-toolbar"><span className="mono library-total">{projects.length.toString().padStart(2,'0')} {t(projects.length===1?'PROJECT':'PROJECTS')}</span><label className="search-box"><Search size={16}/><input data-testid="input-project-search" placeholder={t('Find a project…')} value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button data-testid="button-clear-project-search" onClick={()=>setQuery('')} aria-label={t('Clear search')}><X size={14}/></button>}</label></div>
    {loading?<div className="loading-skeleton" data-testid="status-projects-loading"><i/><i/><i/></div>:error?<div className="error-panel" role="alert" data-testid="status-projects-error"><h2>{t('Projects did not load.')}</h2><p>{t('Your work is still safe. Check your connection and retry.')}</p><button className="btn btn-outline" data-testid="button-retry-projects" onClick={retry}>{t('Try again')}</button></div>:list.length===0?<div className="library-empty"><div className="empty-stack"><Layers3 size={27}/><Plus size={17}/></div><h2>{t(projects.length?'Nothing matches that search.':'A blank page is a good place to start.')}</h2><p>{t(projects.length?'Try a different project title or topic.':'Create a project to turn your first idea into a directed storyboard.')}</p><button className="btn btn-primary" data-testid="button-create-first-project-library" disabled={create.isPending} onClick={createOne}><Plus size={15}/>{t(projects.length?'Create project':'Create your first project')}</button></div>:<div className="project-list">{list.map((p,index)=>{const style=styles.find(s=>s.id===p.styleId)||styles[0];return <article className="project-card" key={p.id} data-testid={`card-project-${p.id}`}><button className="project-image" data-testid={`button-open-project-art-${p.id}`} onClick={()=>open(p)} style={{backgroundImage:style.image?`url("${imageUrl(style.image)}")`:undefined}}><span className="project-index mono">{String(index+1).padStart(2,'0')}</span><span className="project-image-open"><ArrowRight size={16}/></span></button><div className="project-details"><div className="project-title-row"><button className="project-title-link display" data-testid={`button-open-project-${p.id}`} onClick={()=>open(p)}>{p.title||t('Untitled video')}</button><button className="project-quick" data-testid={`button-rename-project-${p.id}`} onClick={()=>rename(p)} aria-label={t('Rename project')}><span className="mono">{t('RENAME')}</span></button></div><p className="project-topic">{p.topic||t('No idea added yet')}</p><div className="project-tags"><span>{t(style.name)}</span><i/><span>{p.aspectRatio}</span><i/><span>{p.scenes.length} {t('scenes')}</span></div><div className="project-card-foot"><span className="mono">{new Date(p.updatedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><button className="open-project" data-testid={`button-open-project-action-${p.id}`} onClick={()=>open(p)}>{t('Open project')} <ArrowRight size={14}/></button><button className="project-delete" data-testid={`button-delete-project-${p.id}`} aria-label={t('Delete project')} title={t('Delete project')} disabled={remove.isPending} onClick={()=>del(p)}><Trash2 size={15}/></button></div></div></article>})}</div>}
      <div className="library-footnote"><span className="local-dot"/>{t('Only you can access these projects while signed in.')}</div><ActionDialog config={dialog} onClose={()=>setDialog(null)}/></div>;
}

function DownloadsPage({user,onBack,notify}:{user:SessionUser;onBack:()=>void;notify:(message:string)=>void}) {
  const t=translateActive;
  const query=useListDownloadedVideos({query:{queryKey:[...getListDownloadedVideosQueryKey(),user.id]}});
  const remove=useDeleteDownloadedVideo();
  const cache=useQueryClient();
  const videos=(query.data??[]) as DownloadedVideo[];
  const [selectedVideo,setSelectedVideo]=useState<DownloadedVideo|null>(null);
  const [dialog,setDialog]=useState<ActionDialogConfig|null>(null);
  const formatSize=(bytes:number)=>bytes<1024*1024?`${Math.max(1,Math.round(bytes/1024))} KB`:`${(bytes/(1024*1024)).toFixed(1)} MB`;
  const deleteVideo=(video:DownloadedVideo)=>setDialog({title:'Delete this video?',message:t('“{{title}}” and its stored MP4 will be permanently deleted to free storage space. This cannot be undone.',{title:video.title||t('Untitled video')}),confirmLabel:'Delete video',tone:'danger',onConfirm:()=>remove.mutate({id:video.id},{onSuccess:()=>{cache.invalidateQueries({queryKey:getListDownloadedVideosQueryKey()});setSelectedVideo(current=>current?.id===video.id?null:current);notify('Video deleted and storage freed');},onError:error=>notify(errorText(error))})});
  return <div className="library-page downloads-page fade-in">
    <div className="library-heading"><div><PageBack onClick={onBack} label="Back to studio"/><div className="eyebrow"><span className="eyebrow-line"/>{t('YOUR PRIVATE VIDEO FILES')}</div><h1 className="display">{t('Downloaded videos')}<span className="heading-period">.</span></h1><p>{t('Preview your renders, prepare platform-specific captions, and share them when ready.')}</p></div></div>
    <div className="library-toolbar"><span className="mono library-total" data-testid="text-download-count">{String(videos.length).padStart(2,'0')} MP4 {t(videos.length===1?'FILE':'FILES')}</span><span className="downloads-storage-note"><LockKeyhole size={13}/>{t('Private to your account')}</span></div>
    {query.isLoading?<div className="loading-skeleton" data-testid="status-downloads-loading"><i/><i/></div>:query.isError?<div className="error-panel" role="alert" data-testid="status-downloads-error"><h2>{t('Your downloads did not load.')}</h2><p>{t('Your saved MP4 files are still safe. Check your connection and retry.')}</p><button className="btn btn-outline" data-testid="button-retry-downloads" onClick={()=>query.refetch()}>{t('Try again')}</button></div>:videos.length===0?<div className="library-empty downloads-empty" data-testid="status-downloads-empty"><div className="download-empty-icon"><Download size={24}/></div><h2>{t('Your video library is ready.')}</h2><p>{t('New renders appear here automatically. MP4s downloaded before this library was added cannot be found automatically; render them again to add them.')}</p><button className="btn btn-primary" data-testid="button-open-studio-from-downloads" onClick={onBack}>{t('Open studio')} <ArrowRight size={15}/></button></div>:<div className="download-list">{videos.map((video,index)=><article className="download-card" key={video.id} data-testid={`card-download-${video.id}`}><div className={`download-art ${video.aspectRatio==='9:16'?'portrait':'landscape'}`}><span className="download-art-index mono">{String(videos.length-index).padStart(2,'0')}</span><Film size={27}/><span className="download-format mono">MP4</span></div><div className="download-details"><div className="download-details-top"><span className="mono">{video.aspectRatio} · {formatRuntime(video.durationSeconds)}</span><span className="mono">{formatSize(video.byteSize)}</span></div><h2>{video.title||t('Untitled video')}</h2><p className="download-topic">{video.topic||t('No topic added')}</p><div className="download-card-foot"><span className="mono">{new Date(video.createdAt).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})}</span><div className="download-card-actions"><button className="btn btn-outline view-share-button" type="button" data-testid={`button-view-share-${video.id}`} onClick={()=>setSelectedVideo(video)}><Eye size={13}/>{t('View & share')}</button><a className="btn btn-primary download-again" data-testid={`button-download-again-${video.id}`} href={`/api/videos/downloads/${video.id}/file`}><Download size={14}/>{t('Download MP4')}</a><button className="btn btn-danger-outline delete-video-button" type="button" data-testid={`button-delete-video-${video.id}`} disabled={remove.isPending} aria-label={`${t('Delete video')}: ${video.title}`} title={t('Delete video')} onClick={()=>deleteVideo(video)}><Trash2 size={14}/></button></div></div></div></article>)}</div>}
    <div className="library-footnote"><span className="local-dot"/>{t('Social accounts are not connected here; sharing opens the selected platform for you to upload manually.')}</div>
    <VideoShareDialog video={selectedVideo} onClose={()=>setSelectedVideo(null)} notify={notify}/>
    <ActionDialog config={dialog} onClose={()=>setDialog(null)}/>
  </div>;
}

function StylesPage({selected,engine,onChoose,onBack}:{selected:string;engine:'model'|'code';onChoose:(s:Style)=>void;onBack:()=>void}) {
  const t=translateActive;
  const [filter,setFilter]=useState<'all'|'model'|'code'>('all');const [query,setQuery]=useState('');
  const filtered=styles.filter(s=>(filter==='all'||s.engine===filter)&&`${s.name} ${t(s.name)} ${s.desc} ${t(s.desc)} ${(s.featureTags??[]).map(tag=>`${tag} ${t(tag)}`).join(' ')}`.toLowerCase().includes(query.toLowerCase()));
  const groups:{key:'model'|'code';title:string;sub:string;code:string}[]=[{key:'model',title:'Model Engine',sub:'Prompt-led visual direction',code:'A SERIES'},{key:'code',title:'Code Engine',sub:'Structured, reproducible scenes',code:'B SERIES'}];
  const modelCount=styles.filter(style=>style.engine==='model').length;
  const codeCount=styles.filter(style=>style.engine==='code').length;
  return <div className="library-page styles-page fade-in"><div className="library-heading"><div><PageBack onClick={onBack} label="Back to studio"/><div className="eyebrow"><span className="eyebrow-line"/>{t('THE LOOK OF THE STORY')}</div><h1 className="display">{t('Style library')}<span className="heading-period">.</span></h1><p>{t('Pick a visual language before you build the frames.')}</p></div><div className="current-style"><span className="current-label mono">{t('CURRENT DIRECTION')}</span><b>{t(styles.find(s=>s.id===selected)?.name ?? '')}</b><small>{t(engine==='model'?'Model Engine':'Code Engine')}</small></div></div><div className="library-toolbar"><div className="filter-tabs"><button className={filter==='all'?'filter-tab on':''} data-testid="filter-styles-all" onClick={()=>setFilter('all')}>{t('All styles')} <span>{styles.length}</span></button><button className={filter==='model'?'filter-tab on':''} data-testid="filter-styles-model" onClick={()=>setFilter('model')}>{t('Model Engine')} <span>{modelCount}</span></button><button className={filter==='code'?'filter-tab on':''} data-testid="filter-styles-code" onClick={()=>setFilter('code')}>{t('Code Engine')} <span>{codeCount}</span></button></div><label className="search-box"><Search size={16}/><input data-testid="input-style-search" placeholder={t('Search the library…')} value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button data-testid="button-clear-style-search" onClick={()=>setQuery('')} aria-label={t('Clear search')}><X size={14}/></button>}</label></div>{groups.map(group=>{const items=filtered.filter(s=>s.engine===group.key);if(!items.length)return null;return <section className="style-group" key={group.key}><div className="group-head"><div><span className="mono group-code">{group.code}</span><h2 className="display">{t(group.title)}</h2><p>{t(group.sub)}</p></div><span className="group-count mono">{String(items.length).padStart(2,'0')} {t('STYLES')}</span></div><div className="style-grid">{items.map((style,i)=><button key={style.id} data-testid={`button-select-style-${style.id}`} className={`style-card ${style.id===selected?'chosen':''}`} onClick={()=>onChoose(style)}><div className="style-image" style={style.image?{backgroundImage:`url("${imageUrl(style.image)}")`}:{}}><span className="style-number mono">{style.id}</span>{style.id===selected&&<span className="selected-mark"><Check size={14}/> {t('SELECTED')}</span>}<span className="style-image-arrow"><ArrowRight size={16}/></span></div><div className="style-card-copy"><h3>{t(style.name)}</h3><p>{t(style.desc)}</p>{style.featureTags&&<div className="style-feature-tags">{style.featureTags.map(tag=><span key={tag} data-testid={`tag-style-feature-${style.id}-${tag.toLowerCase().replaceAll(' ','-')}`}>{t(tag)}</span>)}</div>}<span className="style-use">{t(style.id===selected?'CURRENT STYLE':'USE THIS STYLE')} <ArrowRight size={13}/></span></div><span className="style-card-num mono">0{i+1}</span></button>)}</div></section>})}{filtered.length===0&&<div className="library-empty compact-empty"><Search size={26}/><h2>{t('No style found.')}</h2><p>{t('Try a shorter search or switch the engine filter.')}</p><button className="text-link" data-testid="button-clear-style-filters" onClick={()=>{setQuery('');setFilter('all')}}>{t('Clear filters')} <X size={13}/></button></div>}<div className="styles-note"><Film size={17}/><span>{t('Cartoon series styles add recurring characters, expressive reactions, scene-matched sets, and animated emphasis text.')}</span></div></div>;
}

function SettingsPage({user,notify,onBack}:{user:SessionUser;notify:(s:string)=>void;onBack:()=>void}) {
  const t=translateActive;
  const {locale,setLocale}=useI18n();
  const cache=useQueryClient();
  const providers=useListSocialProviders({query:{queryKey:getListSocialProvidersQueryKey()}});
  const saveSocialProfile=useUpdateSocialProviderProfile();
  const change=useChangePassword();
  const savePreferences=useUpdateUserPreferences();
  const [currentPassword,setCurrentPassword]=useState('');const [newPassword,setNewPassword]=useState('');const [confirmation,setConfirmation]=useState('');const [error,setError]=useState('');
  const submit=(e:FormEvent)=>{e.preventDefault();setError('');if(newPassword.length<6){setError(t('Use at least 6 characters for your new password.'));return;}if(newPassword!==confirmation){setError(t('The new passwords do not match.'));return;}change.mutate({data:{currentPassword,newPassword}},{onSuccess:()=>{setCurrentPassword('');setNewPassword('');setConfirmation('');cache.invalidateQueries({queryKey:getGetCurrentUserQueryKey()});notify('Password changed');},onError:e=>setError(errorText(e))});};
  const persistLanguages=(nextLocale:LanguageCode,nextContentLanguage:LanguageCode)=>{
    const previous=locale;
    setLocale(nextLocale);
    savePreferences.mutate({data:{locale:nextLocale,contentLanguage:nextContentLanguage}},{onSuccess:updated=>{cache.setQueryData(getGetCurrentUserQueryKey(),updated);setLocale(updated.locale);notify('Language preferences saved');},onError:e=>{setLocale(previous);notify(errorText(e));}});
  };
  const persistSocialProfile=(provider:SocialProviderStatus['provider'],profileUrl:string|null)=>{
    saveSocialProfile.mutate({provider,data:{profileUrl}},{onSuccess:()=>{cache.invalidateQueries({queryKey:getListSocialProvidersQueryKey()});notify('Social profile link saved');},onError:error=>notify(errorText(error))});
  };
  const status=providers.data as SocialProviderStatus[]|undefined;
  return <div className="settings-page fade-in"><div className="library-heading"><div><PageBack onClick={onBack} label="Back to studio"/><div className="eyebrow"><span className="eyebrow-line"/>{t('ACCOUNT & ACCESS')}</div><h1 className="display">{t('Settings')}<span className="heading-period">.</span></h1><p>{t('Keep account access clear and connected services honest.')}</p></div></div>
    <section className="settings-panel profile-panel"><div className="settings-icon"><UserRound size={20}/></div><div className="settings-panel-content"><span className="mono settings-label">{t('PROFILE')}</span><h2>{t('Your account')}</h2><div className="profile-grid"><div><small>{t('FULL NAME')}</small><strong data-testid="text-profile-full-name">{user.fullName}</strong></div><div><small>{t('USERNAME')}</small><strong data-testid="text-profile-username">@{user.username}</strong></div><div><small>{t('ROLE')}</small><strong data-testid="text-profile-role">{t(user.role)}</strong></div></div></div></section>
    <section className="settings-panel"><div className="settings-icon"><Layers3 size={20}/></div><div className="settings-panel-content"><span className="mono settings-label">{t('LANGUAGE PREFERENCES')}</span><h2>{t('Language')}</h2><p className="settings-copy">{t('Choose an interface language and a default language for new video content. Each project can use a different content language.')}</p><div className="language-preference-grid"><label>{t('App language')}<select data-testid="select-account-locale" value={locale} disabled={savePreferences.isPending} onChange={e=>persistLanguages(e.target.value as LanguageCode,user.contentLanguage)}><option value="en">English</option><option value="am">አማርኛ</option><option value="ar">العربية</option></select></label><label>{t('Default video content language')}<select data-testid="select-default-content-language" value={user.contentLanguage} disabled={savePreferences.isPending} onChange={e=>persistLanguages(locale,e.target.value as LanguageCode)}><option value="en">English</option><option value="am">አማርኛ</option><option value="ar">العربية</option></select></label></div>{savePreferences.isPending&&<small className="language-saving">{t('Saving language preferences…')}</small>}</div></section>
    {user.mustChangePassword&&<div className="must-change-notice" role="status" data-testid="status-password-change-required"><KeyRound size={17}/><div><strong>A password change is required.</strong><span>Your administrator-issued temporary password is one-time use. Choose a new password below.</span></div></div>}
    <section className="settings-panel"><div className="settings-icon"><LockKeyhole size={20}/></div><div className="settings-panel-content"><span className="mono settings-label">{t('PASSWORD')}</span><h2>{t('Change your password')}</h2><p className="settings-copy">{t('Choose a unique password with at least 6 characters. Passwords are never stored in your browser.')}</p><form className="password-form" onSubmit={submit}><PasswordField label="Current password" testId="input-current-password" autoComplete="current-password" value={currentPassword} onChange={setCurrentPassword}/><PasswordField label="New password" testId="input-new-password" autoComplete="new-password" minLength={6} value={newPassword} onChange={setNewPassword}/><PasswordField label="Confirm new password" testId="input-confirm-password" autoComplete="new-password" minLength={6} value={confirmation} onChange={setConfirmation}/>{error&&<div className="form-error" role="alert" data-testid="status-password-error">{error}</div>}<button className="btn btn-primary" data-testid="button-change-password" disabled={change.isPending}>{change.isPending?t('Updating…'):t('Update password')} <ArrowRight size={15}/></button></form></div></section>
    <section className="settings-panel social-panel"><div className="settings-icon"><Layers3 size={20}/></div><div className="settings-panel-content"><span className="mono settings-label">{t('PUBLISHING CONNECTIONS')}</span><h2>{t('Social accounts')}</h2><p className="settings-copy">{t('Save your profile link for reference. A URL does not connect your account or authorize posting. Automatic publishing requires official provider authorization, which is not configured yet.')}</p>{providers.isLoading?<div className="loading-skeleton compact-skeleton" data-testid="status-social-loading"><i/><i/></div>:providers.isError?<div className="error-panel compact-error" role="alert" data-testid="status-social-error"><p>{t('Provider status is unavailable right now.')}</p><button className="text-link" data-testid="button-retry-social" onClick={()=>providers.refetch()}>{t('Retry status')} <ArrowRight size={13}/></button></div>:<div className="provider-list">{(status??[]).map(provider=><ProviderRow key={provider.provider} provider={provider} saving={saveSocialProfile.isPending} onSave={persistSocialProfile}/>)}</div>}</div></section>
    <div className="recovery-note"><Shield size={17}/><p><strong>Lost your password?</strong> Username-only accounts cannot self-recover by email. Ask an administrator to issue a one-time temporary password, then change it after signing in.</p></div>
  </div>;
}
function ProviderRow({provider,saving,onSave}:{provider:SocialProviderStatus;saving:boolean;onSave:(provider:SocialProviderStatus['provider'],profileUrl:string|null)=>void}) {
  const t=translateActive;
  const [profileUrl,setProfileUrl]=useState(provider.profileUrl??'');
  useEffect(()=>setProfileUrl(provider.profileUrl??''),[provider.profileUrl]);
  const normalized=profileUrl.trim();
  const saved=provider.profileUrl??'';
  const changed=normalized!==saved;
  return <div className="provider-row" data-testid={`status-provider-${provider.provider}`}>
    <div className={`provider-mark ${provider.provider}`}>{provider.label.slice(0,1)}</div>
    <div className="provider-info"><strong>{provider.label}</strong><span data-testid={`text-provider-state-${provider.provider}`}>{provider.connected?provider.accountName??t('Connected'):provider.profileUrl?t('Profile link saved'):t(provider.note||'Setup required — provider app not configured')}</span></div>
    <span className={`provider-state ${provider.configured?'ready':'setup'}`}>{t(provider.connected?'Connected':provider.configured?'Ready':'Setup required')}</span>
    <form className="provider-profile-form" onSubmit={event=>{event.preventDefault();onSave(provider.provider,normalized||null);}}>
      <label className="provider-url-field"><span>{t('Profile URL')}</span><input type="url" inputMode="url" autoComplete="url" maxLength={500} value={profileUrl} onChange={event=>setProfileUrl(event.target.value)} placeholder={provider.provider==='youtube'?'https://youtube.com/@yourchannel':`https://${provider.provider}.com/yourprofile`} aria-label={`${provider.label} ${t('Profile URL')}`} data-testid={`input-social-profile-${provider.provider}`}/></label>
      <button className="btn btn-outline provider-save" type="submit" disabled={!changed||saving} data-testid={`button-save-social-profile-${provider.provider}`}>{saving?t('Saving…'):t(normalized?'Save link':'Remove link')}</button>
    </form>
  </div>;
}

function AdminPage({userId,notify,onBack}:{userId:string;notify:(s:string)=>void;onBack:()=>void}) {
  const t=translateActive;
  const query=useListAdminUsers({query:{queryKey:getListAdminUsersQueryKey()}});const role=useUpdateUserRole();const reset=useResetUserPassword();const cache=useQueryClient();
  const [temporary,setTemporary]=useState<{id:string;username:string;password:string}|null>(null);
  const [dialog,setDialog]=useState<ActionDialogConfig|null>(null);
  const users=(query.data??[]) as AdminUser[];
  const setRole=(u:AdminUser,next:'admin'|'user')=>{const removingSelf=u.id===userId&&next==='user';setDialog({title:removingSelf?'Remove your admin access?':t('Change @{{username}}’s role?',{username:u.username}),message:removingSelf?'You will leave the admin desk after this change. The server will prevent removing the last administrator.':t('This changes @{{username}} from {{currentRole}} to {{nextRole}}.',{username:u.username,currentRole:t(u.role),nextRole:t(next)}),confirmLabel:next==='admin'?'Make administrator':'Change to user',tone:next==='user'?'danger':undefined,onConfirm:()=>role.mutate({id:u.id,data:{role:next}},{onSuccess:()=>{cache.invalidateQueries({queryKey:getListAdminUsersQueryKey()});notify('Account role updated');},onError:e=>notify(errorText(e))})});};
  const resetPass=(u:AdminUser)=>setDialog({title:'Issue a temporary password?',message:t('A one-time password for @{{username}} will be displayed once. Their existing sessions will be signed out.',{username:u.username}),confirmLabel:'Issue password',onConfirm:()=>reset.mutate({id:u.id},{onSuccess:r=>{cache.invalidateQueries({queryKey:getListAdminUsersQueryKey()});setTemporary({id:u.id,username:r.username,password:r.temporaryPassword});},onError:e=>notify(errorText(e))})});
  return <div className="admin-page fade-in"><div className="library-heading"><div><PageBack onClick={onBack} label="Back to settings"/><div className="eyebrow"><span className="eyebrow-line"/>{t('RESTRICTED · ADMINISTRATORS ONLY')}</div><h1 className="display">{t('Admin desk')}<span className="heading-period">.</span></h1><p>{t('Manage account roles and issue one-time password resets.')}</p></div><div className="admin-shield"><Shield size={18}/> {t('ADMIN ACCESS')}</div></div>
    {temporary&&<div className="temporary-password" role="alert" data-testid="status-temporary-password"><div><span className="mono">{t('ONE-TIME TEMPORARY PASSWORD')} · @{temporary.username}</span><strong>{temporary.password}</strong><small>{t('Share securely with this user. This password is not saved and will disappear if you leave this page.')}</small></div><button className="btn btn-outline" data-testid="button-dismiss-temporary-password" onClick={()=>setTemporary(null)}><ArrowLeft size={14}/>{t('Back to admin desk')}</button></div>}
    {query.isLoading?<div className="loading-skeleton" data-testid="status-admin-loading"><i/><i/><i/></div>:query.isError?<div className="error-panel" role="alert" data-testid="status-admin-error"><h2>{t('Accounts did not load.')}</h2><p>{t('Admin account data could not be retrieved.')}</p><button className="btn btn-outline" data-testid="button-retry-admin" onClick={()=>query.refetch()}>{t('Try again')}</button></div>:<div className="admin-table-wrap"><div className="admin-table-heading"><span className="mono">{users.length} {t('ACCOUNTS')}</span><span className="mono">{t('USERNAME-BASED ACCESS')}</span></div><div className="admin-table"><div className="admin-row admin-head"><span>{t('ACCOUNT')}</span><span>{t('PROJECTS')}</span><span>{t('STATUS')}</span><span>{t('ROLE & ACTIONS')}</span></div>{users.map(u=><div className="admin-row" key={u.id} data-testid={`row-admin-user-${u.id}`}><div className="admin-account"><span className="avatar">{initials(u.fullName)}</span><div><strong data-testid={`text-admin-name-${u.id}`}>{u.fullName}</strong><small>@{u.username} · {t('Joined')} {new Date(u.createdAt).toLocaleDateString()}</small></div></div><span className="admin-project-count" data-testid={`text-admin-project-count-${u.id}`}>{u.projectCount}</span><span className={`admin-user-state ${u.mustChangePassword?'pending':'active'}`} data-testid={`status-admin-password-${u.id}`}>{t(u.mustChangePassword?'Password change required':'Active')}</span><div className="admin-actions"><select data-testid={`select-user-role-${u.id}`} value={u.role} aria-label={`${t('Role for')} ${u.username}`} onChange={e=>setRole(u,e.target.value as 'admin'|'user')} disabled={role.isPending}><option value="user">{t('User')}</option><option value="admin">{t('Admin')}</option></select><button className="btn btn-outline reset-user-button" data-testid={`button-reset-password-${u.id}`} disabled={reset.isPending} onClick={()=>resetPass(u)}><KeyRound size={13}/>{reset.isPending?t('Issuing…'):t('Issue reset')}</button></div></div>)}</div></div>}
    <div className="admin-footnote"><LockKeyhole size={15}/><span>{t('Temporary passwords are displayed once in this session only. Ask users to change them immediately.')}</span></div><ActionDialog config={dialog} onClose={()=>setDialog(null)}/>
  </div>;
}

function NotFound({back}:{back:()=>void}) { const t=translateActive;return <div className="not-found"><span className="mono">{t('404 · WRONG SET')}</span><h1 className="display">{t('This scene isn’t in the script.')}</h1><p>{t('Let’s get back to your production desk.')}</p><button className="btn btn-primary" data-testid="button-back-to-studio" onClick={back}><ArrowLeft size={15}/>{t('Back to the studio')}</button></div>; }

export default App;
